 for address,size,name,digest in METHODS:
  if symbols.get(name)!=(address,size):raise ValueError('concrete symbol identity mismatch: '+name)
  if sha(game.read(address,size))!=digest:raise ValueError('method mismatch: '+name)
 if struct.unpack('<I',game.read(0x2f671d0,4))[0]!=16:raise ValueError('current version mismatch')
 calls=[(0x2b4f087,0x1f73a50),(0x2b4f09a,0x1f8ff50),(0x2b4f0ad,0x1eb9310),(0x2b4f0c0,0x1f4cb40),(0x2b4f0d3,0x1f84390),(0x2b4f0e6,0x1f66d50),(0x2b4f0f9,0x1f35f50)]
 for address,target in calls:game.call(address,target)
 command=['gdb','-nx','-batch',str(a.assets/'libGameCore_XP2.so')]
 for name in TYPES:command+=['-ex',"ptype /o 'GameCore::Player::"+name+"'"]
