 sources={str(x.relative_to(ROOT)):sha(x.read_bytes())for x in paths}
 subprocess.run(['cargo','build','--offline','-p','c6-core'],cwd=ROOT,check=True)
 if sources!={str(x.relative_to(ROOT)):sha(x.read_bytes())for x in paths}:raise ValueError('source changed during build')
 reports=[]
 with tempfile.TemporaryDirectory(prefix='c6-resources-')as tmp:
  tmp=Path(tmp);harness=HARNESS.replace('MODULE',str(ROOT/'crates/c6-core/src/player_resources.rs'));(tmp/'candidate.rs').write_text(harness)
  cmd=['rustc','--edition=2021','-Dwarnings',str(tmp/'candidate.rs'),'--extern','c6_core='+str(ROOT/'target/debug/libc6_core.rlib'),'-L','dependency='+str(ROOT/'target/debug/deps')]
  subprocess.run(cmd+['-o',str(tmp/'candidate')],check=True)
  subprocess.run(cmd+['--test','-o',str(tmp/'tests')],check=True)
  subprocess.run([str(tmp/'tests')],check=True)
  candidate_sha=sha((tmp/'candidate').read_bytes())
  for identity,trace_name,trace_sha in FIXTURES:
   data=gzip.decompress((a.private_root/'evidence/linux-game-load/canonical'/(identity+'.bin.gz')).read_bytes())
   if sha(data)!=identity:raise ValueError('Core identity mismatch')
   trace=gzip.decompress((a.private_root/'evidence/linux-save-normalization/checkpoint-203-owners'/trace_name).read_bytes())
   if sha(trace)!=trace_sha:raise ValueError('owner trace identity mismatch')
   rows=[json.loads(x)for x in trace.splitlines()]
   cuts=sorted([x for x in rows if x.get('event')=='owner'and x.get('save')==1 and x.get('owner')=='GameCore::Player::Resources'],key=lambda x:x['start'])
   if not cuts:raise ValueError('no Resources validation cuts')
   observations=[];digests=[];total=0
   for cut in cuts:
    payload=data[cut['start']:cut['end']];(tmp/'in').write_bytes(payload)
    result=subprocess.check_output([str(tmp/'candidate'),str(tmp/'in'),str(tmp/'out')],text=True)
    if (tmp/'out').read_bytes()!=payload:raise ValueError('saved record differs')
    words=[int(x)for x in result.split()]
    if words[0]!=len(payload)or words[2]!=struct.unpack_from('<I',payload,4)[0]:raise ValueError('typed prefix mismatch')
    total+=len(payload);observations.append(words);digests.append(sha(payload))
   reports.append(dict(stream_sha256=identity,trace_sha256=trace_sha,records=len(cuts),record_bytes=total,record_bytes_meaning="sum_of_all_records_in_this_stream",first_record_bytes=cuts[0]["end"]-cuts[0]["start"],first_observed_range=[cuts[0]['start'],cuts[0]['end']],ordered_record_digests_sha256=sha(json.dumps(digests,separators=(',',':')).encode()),typed_observations_sha256=sha(json.dumps(observations,separators=(',',':')).encode())))
 report=dict(schema='c6-linux-player-resources-v1',checks_passed=True,gamecore_sha256=GAME_SHA,host_sha256=HOST_SHA,current_version=16,version_address='0x2f671d0',methods=[dict(address=hex(x),size=n,name=name,sha256=h)for x,n,name,h in METHODS],direct_calls=[dict(address=hex(x),target=hex(y))for x,y in calls],dwarf_sha256=sha(dwarf.encode()),candidate_sources=sources,candidate_sha256=candidate_sha,harness_sha256=sha(harness.encode()),audit_source_sha256=sha(Path(__file__).read_bytes()),fixtures=reports,source_only_tests=6,original_execution=False,private_writes=False,legacy_versions=False,bool_fields="hash_array_values_and_one_scalar",attribution_reference_revision="5af389445118bed2bdebf7a8a42b219c8fba5175",reference_role="discovery_only",complete_current_resources_wire=True,definition_remapping=False,native_read_fixups=False,full_player=False,world_import=False,gameplay_state=False,actions=False,turns=False,next_player_component='Stats',unknown_save_bytes_masked=False,recorded_raw_save_load_difference_bytes=89198)
 a.output.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps(dict(checks_passed=True,methods=len(METHODS),fixtures=reports)))
